P17_OLD = 'print()\n\n\ndef _b2_interior_fit(inpainted_bgr, x, y, w, h, quad):\n    """MANGABD-009 B2 RF-17: bubble-interior fit box (tilted render)।\n\n    Owner REJECT 57ac480-এর D1/D2-এর শিকড়: tilted render-এর fit dims\n    এসেছিল quad side-lengths থেকে — যেটা হয়) spike/ভারী-art-এ ফুলে\n    ওঠা contaminated quad, নয়) নিজের আঁকা text-ink-এর PCA rect —\n    দুটোই বাস্তব text-allowed area নয়। এই helper render-time-এ\n    inpainted crop থেকে সত্যি area বের করে: border থেকে light flood =\n    "outside"; ring-এর ভেতরের light = bubble interior; quad-এর\n    (u, v) axes-এ তার projection extents-ই reading-frame fit box।\n\n    Returns (fit_w, fit_h, interior_mean_gray, centroid_x,\n    centroid_y), নাহলে None — তাহলে আগের quad-side-lengths path-ই\n    চলে (হুবহু পুরনো bytes)।\n    """\n    try:\n        H, W = inpainted_bgr.shape[:2]\n        x1, y1 = max(0, x - 2), max(0, y - 2)\n        x2, y2 = min(W, x + w + 2), min(H, y + h + 2)\n        if x2 - x1 < 16 or y2 - y1 < 16:\n            return None\n        crop = inpainted_bgr[y1:y2, x1:x2]\n        gray = cv2.cvtColor(crop, cv2.COLOR_BGR2GRAY)\n        ink = (gray < 100).astype(np.uint8) * 255\n        if int(ink.sum() // 255) < 30:\n            _otsu, _ = cv2.threshold(\n                gray, 0, 255, cv2.THRESH_BINARY_INV + cv2.THRESH_OTSU)\n            ink = (gray < max(int(_otsu), 40)).astype(np.uint8) * 255\n        _nl, _lab, _st, _ = cv2.connectedComponentsWithStats(\n            ink, connectivity=8)\n        if _nl > 1:\n            _keep = np.zeros_like(ink)\n            for _ci in range(1, _nl):\n                if _st[_ci, cv2.CC_STAT_AREA] >= 6:\n                    _keep[_lab == _ci] = 255\n            if int(_keep.sum() // 255) >= 30:\n                ink = _keep\n        _light = (ink == 0)\n        _ff = np.pad(_light, 1, constant_values=True).astype(np.uint8)\n        _ffmask = np.zeros((_ff.shape[0] + 2, _ff.shape[1] + 2), np.uint8)\n        cv2.floodFill(_ff, _ffmask, (0, 0), 2)\n        _outside = (_ff == 2)[1:-1, 1:-1]\n        interior = _light & ~_outside\n        if int(interior.sum()) < 400:\n            return None\n        _q = np.asarray(quad, dtype=np.float64)\n        if _q.shape != (4, 2):\n            return None\n        _u = _q[1] - _q[0]\n        _v = _q[3] - _q[0]\n        _nu = float(np.linalg.norm(_u))\n        _nv = float(np.linalg.norm(_v))\n        if _nu < 1.0 or _nv < 1.0:\n            return None\n        _u = _u / _nu\n        _v = _v / _nv\n        _ys, _xs = np.nonzero(interior)\n        _pts = np.stack(\n            [_xs.astype(np.float64), _ys.astype(np.float64)], 1)\n        _pu = _pts @ _u\n        _pv = _pts @ _v\n        _fw = float(_pu.max() - _pu.min())\n        _fh = float(_pv.max() - _pv.min())\n        if _fw < 60.0 or _fh < 40.0:\n            return None\n        _imean = float(gray[interior].mean())\n        # cloud centroid (page coords) — art-টেনে নেওয়া asymmetric\n        # bbox-এ bbox-center আর bubble-center আলাদা হয় (E3-তে 15px);\n        # interior-path paste এই centroid-এই বসে।\n        _icx = float(_xs.mean()) + x1\n        _icy = float(_ys.mean()) + y1\n        # ellipse-aware box: তির্যক-frame extent box-এর কোণাগুলো\n        # cloud-এর বাইরে পড়ে (চওড়া+লম্বা block-এর কোণা poke করে)।\n        # cloud-এর chord-profile ধরে shrink করি যতক্ষণ না avail box\n        # (fw-2p)x(fh-2p) পুরোপুরি cloud-এর ভেতরে থাকে: centered\n        # rect hw x hh ন্তরে থাকে <=> hw <= v-window-এর min u-chord।\n        _order = np.argsort(np.round(_pv).astype(int), kind="stable")\n        _pv_s = np.round(_pv).astype(int)[_order]\n        _pu_s = _pu[_order]\n        _bnd = np.nonzero(np.diff(_pv_s))[0] + 1\n        _starts = np.concatenate([[0], _bnd])\n        _ends = np.concatenate([_bnd, [len(_pv_s)]])\n        _chord = {}\n        for _s, _e in zip(_starts, _ends):\n            if _e - _s >= 3:\n                _chord[int(_pv_s[_s])] = float(\n                    _pu_s[_s:_e].max() - _pu_s[_s:_e].min()) / 2.0\n        if not _chord:\n            return None\n        _vc = int(round(float(_pv.mean())))\n        _fw = _fw * 0.90\n        _fh = _fh * 0.90\n        for _ in range(6):\n            _p = max(4.0, 0.08 * min(_fw, _fh))\n            _hh = (_fh - 2 * _p) / 2.0\n            _hw = (_fw - 2 * _p) / 2.0\n            _win = [c for b, c in _chord.items()\n                    if abs(b - _vc) <= _hh + 1.0]\n            if not _win:\n                return None\n            _mc = min(_win)\n            if _hw <= _mc:\n                break\n            _fw = 2.0 * (_mc + _p)\n        if _fw < 60.0 or _fh < 40.0:\n            return None\n        return (int(_fw), int(_fh), _imean, _icx, _icy)\n    except Exception:\n        return None\n\n\nprint("  ✅ B2 interior-fit ready (MANGABD-009 B2 RF-17)")\n'

