P26_OLD = '# Test 21: B2 RF-17 — layout parity on tilted bubbles: interior fit +\n# interior color। Owner REJECT 57ac480-এর D1 (spike-inflated quad-এ\n# লাইন-কলাপ্স + bubble-এর বাইরে কালি) আর D2 (অন্ধকার art-ভরা bbox-এর\n# mean সাদা রঙ বেছে নিয়ে white-on-white) — দুটোই এই trap-এ ধরা পড়ে।\ntry:\n    _t21_pid = "__b2_rf17_t21__"\n    _t21_canvas = np.full((760, 940, 3), 255, np.uint8)\n    # region 1 (D1): ring 260x176 at (250,220), spike-INFLATED quad\n    # 330x250 (rotated -12) — pre-fix quad-fit render overflows the\n    # ring interior; post-fix interior-fit stays inside\n    cv2.ellipse(_t21_canvas, (250, 220), (130, 88), 0, 0, 360,\n                (30, 30, 30), 4)\n    # region 2 (D2): ring 220x150 at (700,470) inside a dark hatched\n    # box (mean < 160) — pre-fix bbox-mean picks WHITE (invisible on\n    # the white interior); post-fix interior-mean picks BLACK\n    for _t21_y in range(340, 610, 20):\n        cv2.line(_t21_canvas, (530, _t21_y), (870, _t21_y),\n                 (60, 60, 60), 15)\n    cv2.ellipse(_t21_canvas, (700, 470), (106, 71), 0, 0, 360,\n                (255, 255, 255), -1)\n    cv2.ellipse(_t21_canvas, (700, 470), (110, 75), 0, 0, 360,\n                (30, 30, 30), 4)\n\n    init_page(_t21_pid, width=940, height=760,\n              image_np=_t21_canvas, overwrite=True)\n    save_image_artifact(_t21_pid, "inpainted", _t21_canvas, quality=95)\n\n    _t21_q1 = [[63, 132], [385, 63], [437, 308], [115, 377]]\n    _t21_q2 = [[635, 422], [780, 460], [765, 518], [620, 480]]\n    save_json_artifact(_t21_pid, "detections", [\n        {"id": 1, "page_id": _t21_pid, "x": 60, "y": 80,\n         "width": 380, "height": 300, "quad": _t21_q1,\n         "angle": -12.0, "region_type": "bubble",\n         "detector_class": "text_bubble", "detector_score": 0.9,\n         "parent_bubble_id": None},\n        {"id": 2, "page_id": _t21_pid, "x": 530, "y": 340,\n         "width": 340, "height": 260, "quad": _t21_q2,\n         "angle": 15.0, "region_type": "bubble",\n         "detector_class": "text_bubble", "detector_score": 0.9,\n         "parent_bubble_id": None},\n    ])\n    mark_stage_done(_t21_pid, "detect", meta={"region_count": 2})\n\n    def _t21_row(rid, x, y, w, h, angle):\n        _row = {c: "" for c in TRANSLATION_DF_COLUMNS}\n        _row.update({\n            "page_id": _t21_pid, "page": _t21_pid, "id": int(rid),\n            "region_type": "bubble",\n            "detector_class": "text_bubble",\n            "detector_score": 0.9, "parent_bubble_id": "",\n            "x": int(x), "y": int(y), "width": int(w), "height": int(h),\n            "angle": float(angle), "original_text": "テスト",\n            "translated_text": "", "confidence": 0.9,\n            "ocr_engine": "t21", "is_english": True,\n            "bengali_valid": False, "status": "ok",\n            "reading_order": -1,\n        })\n        return _row\n\n    upsert_translation_rows(_t21_pid, [\n        _t21_row(1, 60, 80, 380, 300, -12.0),\n        _t21_row(2, 530, 340, 340, 260, 15.0),\n    ])\n\n    _t21_df = translation_df\n    for _t21_idx, _t21_r in (\n        _t21_df[_t21_df["page_id"] == _t21_pid].iterrows()\n    ):\n        _t21_df.at[_t21_idx, "translated_text"] = (\n            "এই কী হয়েছে বলো তো? আমি কিছুই বুঝতে পারছি না!"\n            if int(_t21_r["id"]) == 1 else\n            "জলদি এদিকে এসো, একা থেকো না যেন!"\n        )\n    save_translation_df()\n\n    _t21_out = render_page(_t21_pid, force=True)\n\n    def _t21_region_ink(rid, cx, cy, rx, ry):\n        _r = next(d for d in load_json_artifact(\n            _t21_pid, "detections", default=[])\n            if int(d["id"]) == rid)\n        _x, _y = int(_r["x"]), int(_r["y"])\n        _w, _h = int(_r["width"]), int(_r["height"])\n        _roi = np.abs(\n            _t21_out[_y:_y + _h, _x:_x + _w].astype(int)\n            - _t21_canvas[_y:_y + _h, _x:_x + _w].astype(int)\n        ).sum(axis=2)\n        _ink = (_roi > 30)\n        # interior mask (ROI coords): filled ellipse just inside ring\n        _yy, _xx = np.mgrid[_y:_y + _h, _x:_x + _w]\n        _inside = ((_xx - cx) ** 2 / rx ** 2\n                   + (_yy - cy) ** 2 / ry ** 2) <= 1.0\n        return int(_ink.sum()), int((_ink & ~_inside).sum())\n\n    _t21_v1, _t21_o1 = _t21_region_ink(1, 250, 220, 126, 84)\n    _t21_v2, _t21_o2 = _t21_region_ink(2, 700, 470, 106, 71)\n\n    # region 1 line count: the render\'s own fit, replicated exactly\n    # (interior box -> padding -> fit_font_size; deterministic — the\n    # ink-projection band count can\'t separate Bengali lines whose\n    # matras touch, but the render itself draws len(lines) lines)\n    _t21_fit1 = _b2_interior_fit(\n        _t21_canvas, 60, 80, 380, 300, _t21_q1)\n    _t21_nlines = 0\n    if _t21_fit1 is not None:\n        _t21_fw, _t21_fh = _t21_fit1[0], _t21_fit1[1]\n        _t21_pad = max(4, int(min(_t21_fw, _t21_fh) * 0.08))\n        _, _t21_lines, _ = fit_font_size(\n            "এই কী হয়েছে বলো তো? আমি কিছুই বুঝতে পারছি না!",\n            _t21_fw, _t21_fh, bold=False, padding=_t21_pad)\n        _t21_nlines = len(_t21_lines)\n\n    _t21_ok = (_t21_v1 >= 50 and _t21_v2 >= 50\n               and _t21_o1 <= 25 and _t21_o2 <= 25\n               and _t21_nlines >= 2)\n    run_test(\n        "B2 RF-17: interior fit + color (D1 overflow + D2 invisible)",\n        _t21_ok,\n        f"ink(d1/d2)={_t21_v1}/{_t21_v2} "\n        f"outside(d1/d2)={_t21_o1}/{_t21_o2} lines(d1)={_t21_nlines}",\n'

P26_NEW = '# Test 21: B2 RF-18 — original-ink-driven orientation parity। mask GT\n# (minAreaRect + row-profile) -> stored angle -> GT-mirrored tilted\n# render -> rendered ink আবার একই আইনে মাপা: angle <=2 deg, lines\n# ±1, oriented-bbox IoU >= 0.6 (বা side parity ±15%), GT quad-এর\n# বাইরে কালি 0px। Fallback ladder-এর rung-contract-ও এখানেই।\ntry:\n    _t21_font = get_font(26, bold=False)\n    _t21_line = "বাংলা পরীক্ষা লাইন এক দুই তিন"\n    _t21_c = PILImage.new("L", (620, 3 * 42 + 24), 255)\n    _t21_d = ImageDraw.Draw(_t21_c)\n    for _t21_i in range(3):\n        _t21_d.text((14, 8 + _t21_i * 42), _t21_line,\n                    font=_t21_font, fill=0)\n    _t21_r = _t21_c.rotate(-14.0, expand=True,\n                           resample=PILImage.BICUBIC, fillcolor=255)\n    _t21_pg = np.full(\n        (_t21_r.height + 40, _t21_r.width + 40, 3), 255, np.uint8)\n    _t21_pg[20:20 + _t21_r.height, 20:20 + _t21_r.width] = cv2.cvtColor(\n        np.asarray(_t21_r), cv2.COLOR_GRAY2BGR)\n    _t21_g = cv2.cvtColor(_t21_pg, cv2.COLOR_BGR2GRAY)\n    _t21_ys, _t21_xs = np.nonzero(_t21_g < 128)\n    _t21_box = (int(_t21_xs.min()), int(_t21_ys.min()),\n                int(_t21_xs.max() - _t21_xs.min()) + 1,\n                int(_t21_ys.max() - _t21_ys.min()) + 1)\n    _t21_ink = np.zeros(_t21_pg.shape[:2], np.uint8)\n    _t21_ink[_t21_g < 128] = 255\n\n    # (a) mask-GT measurement: angle within 2 deg, 3 lines, quad+gt\n    _t21_ang, _t21_quad, _t21_gt, _t21_meas = _b2_mask_orientation(\n        _t21_ink, *_t21_box)\n    _t21_okA = (_t21_meas and _t21_quad is not None\n                and _t21_gt is not None\n                and abs(_t21_ang + 14.0) <= 2.0\n                and int(_t21_gt["lines"]) == 3)\n\n    # (b) GT-mirrored render through render_bengali_text (b2gt)\n    _t21_qa = np.asarray(_t21_quad, dtype=np.float64)\n    _t21_fw = int(round(max(\n        float(np.linalg.norm(_t21_qa[0] - _t21_qa[1])),\n        float(np.linalg.norm(_t21_qa[2] - _t21_qa[3])))))\n    _t21_fh = int(round(max(\n        float(np.linalg.norm(_t21_qa[0] - _t21_qa[3])),\n        float(np.linalg.norm(_t21_qa[1] - _t21_qa[2])))))\n    _t21_src = PILImage.fromarray(\n        cv2.cvtColor(_t21_pg, cv2.COLOR_BGR2RGB))\n    _t21_out = render_bengali_text(\n        _t21_src.copy(),\n        "এই কী হয়েছে বলো তো? বাংলা পরীক্ষা লাইন এক দুই তিন চার "\n        "পাঁচ ছয় সাত আট নয় দশ এগারো বারো",\n        _t21_box[0], _t21_box[1], _t21_box[2], _t21_box[3],\n        angle=_t21_ang, region_type="bubble",\n        text_color=(0, 0, 0), stroke_width=0,\n        fit_w=_t21_fw, fit_h=_t21_fh,\n        fit_result={"mode": "b2gt", "lines": int(_t21_gt["lines"]),\n                    "spacing": float(_t21_gt["spacing"]),\n                    "cx": float(_t21_gt["cx"]),\n                    "cy": float(_t21_gt["cy"])},\n    )\n    _t21_new = ((np.asarray(_t21_out.convert("L")) < 128)\n                & (np.asarray(_t21_src.convert("L")) >= 128))\n    _t21_nink = int(_t21_new.sum())\n    _t21_rmask = np.zeros(_t21_pg.shape[:2], np.uint8)\n    _t21_rmask[_t21_new] = 255\n    _t21_rys, _t21_rxs = np.nonzero(_t21_new)\n    _t21_rbox = (int(_t21_rxs.min()), int(_t21_rys.min()),\n                 int(_t21_rxs.max() - _t21_rxs.min()) + 1,\n                 int(_t21_rys.max() - _t21_rys.min()) + 1)\n    _t21_rang, _t21_rquad, _t21_rgt, _t21_rmeas = _b2_mask_orientation(\n        _t21_rmask, *_t21_rbox)\n    _t21_okB = (_t21_rmeas and _t21_nink > 200\n                and abs(_t21_rang - _t21_ang) <= 2.0\n                and abs(int(_t21_rgt["lines"]) - 3) <= 1)\n\n    # (c) oriented-bbox IoU >= 0.6 (or side parity +/-15%)\n    _t21_iou = 0.0\n    _t21_sp = 1.0\n    if _t21_rquad is not None:\n        _qa = np.asarray(_t21_quad, dtype=np.float32)\n        _qb = np.asarray(_t21_rquad, dtype=np.float32)\n        _inter, _ = cv2.intersectConvexConvex(_qa, _qb)\n        _aa = cv2.contourArea(_qa)\n        _ab = cv2.contourArea(_qb)\n        _t21_iou = float(_inter / max(1e-6, _aa + _ab - _inter))\n        _fw2 = max(float(np.linalg.norm(_qa[0] - _qa[1])),\n                   float(np.linalg.norm(_qa[2] - _qa[3])))\n        _fh2 = max(float(np.linalg.norm(_qa[0] - _qa[3])),\n                   float(np.linalg.norm(_qa[1] - _qa[2])))\n        _gw2 = max(float(np.linalg.norm(_qb[0] - _qb[1])),\n                   float(np.linalg.norm(_qb[2] - _qb[3])))\n        _gh2 = max(float(np.linalg.norm(_qb[0] - _qb[3])),\n                   float(np.linalg.norm(_qb[1] - _qb[2])))\n        _t21_sp = float(max(abs(_gw2 - _fw2) / max(1.0, _fw2),\n                            abs(_gh2 - _fh2) / max(1.0, _fh2)))\n    _t21_okC = _t21_iou >= 0.6 or _t21_sp <= 0.15\n\n    # (d) containment: rendered ink outside GT quad (+8px) == 0\n    _t21_outside = -1\n    if _t21_rquad is not None:\n        _t21_qm = np.zeros(_t21_pg.shape[:2], np.uint8)\n        cv2.fillPoly(_t21_qm, [np.asarray(\n            _t21_quad, dtype=np.float32).astype(np.int32)], 255)\n        _t21_qm = cv2.dilate(_t21_qm, cv2.getStructuringElement(\n            cv2.MORPH_ELLIPSE, (17, 17)))\n        _t21_outside = int((_t21_new & (_t21_qm == 0)).sum())\n    _t21_okD = _t21_outside == 0\n\n    # (e) ladder rung contract: empty/tiny mask -> NOT measured\n    _t21_e = np.zeros_like(_t21_ink)\n    _, _, _, _t21_m0 = _b2_mask_orientation(_t21_e, *_t21_box)\n    _t21_t = np.zeros_like(_t21_ink)\n    _t21_t[50, 50] = 255\n    _, _, _, _t21_m1 = _b2_mask_orientation(_t21_t, *_t21_box)\n    _t21_okE = (not _t21_m0) and (not _t21_m1)\n\n    run_test(\n        "B2 RF-18: original-ink orientation parity (mask GT -> render)",\n        _t21_okA and _t21_okB and _t21_okC and _t21_okD and _t21_okE,\n        f"gt_ang={_t21_ang} gt_lines="\n        f"{_t21_gt[\'lines\'] if _t21_gt else \'?\'} "\n        f"render_ang={_t21_rang} render_lines="\n        f"{_t21_rgt[\'lines\'] if _t21_rgt else \'?\'} "\n        f"ink={_t21_nink} iou={_t21_iou:.2f} sidedev={_t21_sp:.2f} "\n        f"outpx={_t21_outside} rungs={\'Y\' if _t21_okE else \'N\'}",\n'

